$ErrorActionPreference = 'Stop'
$project = 'C:\xampp\htdocs\PRO\synrcypro-laravel'
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'

Write-Host ''
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ' SYNRGYPRO - FRONTEND FINALIZATION V1' -ForegroundColor Cyan
Write-Host ' FRONTEND ONLY - NO BACKEND CHANGE' -ForegroundColor Cyan
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ''

if (-not (Test-Path (Join-Path $project 'artisan'))) {
    throw "Project Laravel tidak ditemukan: $project"
}

$payload = @(
    @{ Target = 'resources\views\admin-all\mcu-fu\update.blade.php'; Data = '' },
    @{ Target = 'resources\views\admin-all\e-arsip\index.blade.php'; Data = '' },
    @{ Target = 'resources\views\admin-all\e-arsip\trash.blade.php'; Data = '' },
    @{ Target = 'resources\views\admin-all\dashboard.blade.php'; Data = '' },
    @{ Target = 'resources\views\admin-all\layout.blade.php'; Data = '' }
)

foreach ($item in $payload) {
    $target = Join-Path $project $item.Target
    $dir = Split-Path -Parent $target
    New-Item -ItemType Directory -Force -Path $dir | Out-Null

    if (Test-Path $target) {
        Copy-Item $target "$target.bak-$stamp" -Force
        Write-Host "BACKUP: $($item.Target)" -ForegroundColor DarkYellow
    }

    [System.IO.File]::WriteAllBytes(
        $target,
        [System.Convert]::FromBase64String($item.Data)
    )

    Write-Host "OK: $($item.Target)" -ForegroundColor Green
}

Push-Location $project
try {
    & php artisan view:clear
}
finally {
    Pop-Location
}

Write-Host ''
Write-Host 'FRONTEND INSTALL SELESAI' -ForegroundColor Green
Write-Host 'Tidak ada route/controller/service/model yang diubah.' -ForegroundColor Yellow
Write-Host 'Sampah = NEXT sampai backend route dibuat.' -ForegroundColor Yellow
Write-Host 'Activity Feed = Suggestion fallback sampai backend aggregator dibuat.' -ForegroundColor Yellow
